perl -e '
use strict; use warnings;
my $ROOT = "/bench/repo";
my %packages;

sub is_memo_ref {
    my ($text, $prefix) = @_;
    if ($prefix) {
        return $text =~ /\b\Q$prefix\E\.Memo\b(?![A-Za-z_])/;
    } else {
        return $text =~ /(?<![A-Za-z0-9_\.])\*?Memo\b(?![A-Za-z_])/;
    }
}

sub strip_comments {
    my ($line) = @_;
    $line =~ s/\/\/.*$//;
    return $line;
}

find(\&wanted, $ROOT);

sub wanted {
    return unless /\.go$/;
    my $path = $File::Find::name;
    return if $path =~ /\/proto\//;

    open my $fh, "<", $path or return;
    my @lines = <$fh>;
    close $fh;
    my $content = join "", @lines;

    my $rel = $path;
    $rel =~ s/^\Q$ROOT\E\/?//;
    my $pkg_dir = $rel;
    $pkg_dir =~ s/\/[^\/]+$//;
    $pkg_dir = "." if $pkg_dir eq $rel;

    my $alias;
    for (@lines) {
        if (/^\s*(?:(\w+)\s+)?"github\.com\/usememos\/memos\/store"/) {
            $alias = $1 // "store";
            last;
        }
    }

    my $in_root_store = ($pkg_dir eq "store");
    my @refs;
    for my $i (0..$#lines) {
        my $clean = strip_comments($lines[$i]);
        if ($in_root_store) {
            next if $clean =~ /\btype\s+Memo\s+struct\b/;
            push @refs, $i+1 if is_memo_ref($clean, "");
        } elsif ($alias) {
            push @refs, $i+1 if is_memo_ref($clean, $alias);
        }
    }
    return unless @refs;

    $packages{$pkg_dir}{files}{$rel} = 1;
    if (@{$packages{$pkg_dir}{examples} // []} < 3) {
        push @{$packages{$pkg_dir}{examples}}, [$refs[0], substr($lines[$refs[0]-1], 0, 100)];
    }
}

use File::Find;
for my $pkg (sort keys %packages) {
    my $n = scalar keys %{$packages{$pkg}{files}};
    print "=== $pkg ($n files) ===\n";
    my $c = 0;
    for my $f (sort keys %{$packages{$pkg}{files}}) {
        print "  $f\n";
        last if ++$c >= 8;
    }
    print "  ...\n" if $n > 8;
    for my $ex (@{$packages{$pkg}{examples}}) {
        my ($ln, $txt) = @$ex;
        $txt =~ s/^\s+//; $txt =~ s/\s+$//;
        print "    L$ln: $txt\n";
    }
    print "\n";
}
'

